import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { mount } from '@vue/test-utils'

const shellMocks = vi.hoisted(() => ({
  on: vi.fn(),
  off: vi.fn(),
  connect: vi.fn(),
  sendPresenceUpdate: vi.fn(),
  useNotificationRuntime: vi.fn(),
  initChatUploadBackground: vi.fn(async () => {}),
  hasPendingUploadResumeHint: vi.fn(() => false),
  setUploadResumeHint: vi.fn(),
  initChatDocumentDownloadBackground: vi.fn(async () => {}),
  hasPendingDocumentDownloadResumeHint: vi.fn(() => false),
  setDocumentDownloadResumeHint: vi.fn(),
  initChatFileDebugOverlay: vi.fn(),
  setupExpiryTimer: vi.fn(),
  apiFetch: vi.fn(async () => ({})),
  route: { path: '/' },
}))

vi.mock('../composables/useWebSocket', () => ({
  useWebSocket: () => ({
    on: shellMocks.on,
    off: shellMocks.off,
    connect: shellMocks.connect,
    sendPresenceUpdate: shellMocks.sendPresenceUpdate,
  }),
}))

vi.mock('vue-router', () => ({
  useRoute: () => shellMocks.route,
}))

vi.mock('../composables/useNotificationRuntime', () => ({
  useNotificationRuntime: shellMocks.useNotificationRuntime,
}))

vi.mock('../services/chatTransferResumeHints', () => ({
  hasPendingDocumentDownloadResumeHint: shellMocks.hasPendingDocumentDownloadResumeHint,
  hasPendingUploadResumeHint: shellMocks.hasPendingUploadResumeHint,
  setDocumentDownloadResumeHint: shellMocks.setDocumentDownloadResumeHint,
  setUploadResumeHint: shellMocks.setUploadResumeHint,
}))

vi.mock('../services/chatUploadBackground', () => ({
  initChatUploadBackground: shellMocks.initChatUploadBackground,
}))

vi.mock('../services/chatDocumentDownloadBackground', () => ({
  initChatDocumentDownloadBackground: shellMocks.initChatDocumentDownloadBackground,
}))

vi.mock('../composables/chat/useChatFileHandler', () => ({
  initChatFileDebugOverlay: shellMocks.initChatFileDebugOverlay,
}))

vi.mock('../utils/auth', () => ({
  setupExpiryTimer: shellMocks.setupExpiryTimer,
  apiFetch: shellMocks.apiFetch,
}))

describe('AppAuthenticatedShell.vue', () => {
  beforeEach(() => {
    shellMocks.on.mockReset()
    shellMocks.off.mockReset()
    shellMocks.connect.mockReset()
    shellMocks.sendPresenceUpdate.mockReset()
    shellMocks.useNotificationRuntime.mockReset()
    shellMocks.initChatUploadBackground.mockClear()
    shellMocks.hasPendingUploadResumeHint.mockReset()
    shellMocks.hasPendingUploadResumeHint.mockReturnValue(false)
    shellMocks.setUploadResumeHint.mockReset()
    shellMocks.initChatDocumentDownloadBackground.mockClear()
    shellMocks.hasPendingDocumentDownloadResumeHint.mockReset()
    shellMocks.hasPendingDocumentDownloadResumeHint.mockReturnValue(false)
    shellMocks.setDocumentDownloadResumeHint.mockReset()
    shellMocks.initChatFileDebugOverlay.mockClear()
    shellMocks.setupExpiryTimer.mockClear()
    shellMocks.apiFetch.mockReset()
    shellMocks.apiFetch.mockResolvedValue({})
    shellMocks.route.path = '/'
    Object.defineProperty(document, 'hidden', { configurable: true, value: false })
    localStorage.clear()
  })

  afterEach(() => {
    localStorage.clear()
    delete (window as any).deferredPrompt
  })

  it('skips eager background recovery when no pending transfer hint exists and forwards ensureSessionValidation', async () => {
    localStorage.setItem('auth_token', 'jwt')
    localStorage.setItem('refresh_token', 'refresh-token')
    shellMocks.useNotificationRuntime.mockImplementation(({ ensureSessionValidation }) => {
      ;(shellMocks.useNotificationRuntime as any).capturedEnsure = ensureSessionValidation
    })

    const AppAuthenticatedShell = (await import('./AppAuthenticatedShell.vue')).default
    const wrapper = mount(AppAuthenticatedShell, {
      props: { v2Scope: true },
      global: {
        stubs: {
          BottomNav: true,
          SessionApprovalModal: true,
          AppToasts: true,
        },
      },
    })

    expect(shellMocks.initChatUploadBackground).not.toHaveBeenCalled()
    expect(shellMocks.initChatDocumentDownloadBackground).not.toHaveBeenCalled()
    expect(shellMocks.useNotificationRuntime).toHaveBeenCalledWith({
      connect: shellMocks.connect,
      on: shellMocks.on,
      off: shellMocks.off,
      ensureSessionValidation: expect.any(Function),
    })
    expect(shellMocks.setupExpiryTimer).toHaveBeenCalledTimes(1)
    expect(shellMocks.initChatFileDebugOverlay).toHaveBeenCalledTimes(1)
    expect(shellMocks.on).toHaveBeenCalledWith('ws:reconnect', expect.any(Function))
    expect(shellMocks.sendPresenceUpdate).toHaveBeenCalledWith('/', true)
    expect(wrapper.findComponent({ name: 'SessionApprovalModal' }).props('v2Portal')).toBe(true)
    expect(wrapper.findComponent({ name: 'BottomNav' }).props('v2Scope')).toBe(true)

    const ensureSessionValidation = (shellMocks.useNotificationRuntime as any).capturedEnsure
    await ensureSessionValidation()
    expect(shellMocks.apiFetch).toHaveBeenCalledWith('/api/sessions/verify', {
      method: 'POST',
      body: JSON.stringify({ refresh_token: 'refresh-token' }),
    })

    wrapper.unmount()
    expect(shellMocks.off).toHaveBeenCalledWith('ws:reconnect', expect.any(Function))
    expect(shellMocks.sendPresenceUpdate).toHaveBeenLastCalledWith('/', false)
  })

  it('starts background recovery immediately when a pending transfer hint exists', async () => {
    shellMocks.hasPendingUploadResumeHint.mockReturnValue(true)
    shellMocks.hasPendingDocumentDownloadResumeHint.mockReturnValue(true)

    const AppAuthenticatedShell = (await import('./AppAuthenticatedShell.vue')).default
    mount(AppAuthenticatedShell, {
      global: {
        stubs: {
          BottomNav: true,
          SessionApprovalModal: true,
          AppToasts: true,
        },
      },
    })

    await vi.waitFor(() => {
      expect(shellMocks.initChatUploadBackground).toHaveBeenCalledTimes(1)
      expect(shellMocks.initChatDocumentDownloadBackground).toHaveBeenCalledTimes(1)
    })
  })

  it('keeps security layers but omits BottomNav in focused authenticated mode', async () => {
    const AppAuthenticatedShell = (await import('./AppAuthenticatedShell.vue')).default
    const wrapper = mount(AppAuthenticatedShell, {
      props: { v2Scope: true, showDailyNavigation: false },
      global: {
        stubs: {
          BottomNav: true,
          SessionApprovalModal: true,
          AppToasts: true,
        },
      },
    })

    expect(wrapper.findComponent({ name: 'BottomNav' }).exists()).toBe(false)
    expect(wrapper.findComponent({ name: 'SessionApprovalModal' }).props('v2Portal')).toBe(true)
    expect(wrapper.findComponent({ name: 'AppToasts' }).props('v2Scope')).toBe(true)
  })

  it('skips session verification without a refresh token and swallows verification failures', async () => {
    shellMocks.useNotificationRuntime.mockImplementation(({ ensureSessionValidation }) => {
      ;(shellMocks.useNotificationRuntime as any).capturedEnsure = ensureSessionValidation
    })
    shellMocks.apiFetch.mockRejectedValueOnce(new Error('unauthorized'))

    const AppAuthenticatedShell = (await import('./AppAuthenticatedShell.vue')).default
    mount(AppAuthenticatedShell, {
      global: {
        stubs: {
          BottomNav: true,
          SessionApprovalModal: true,
          AppToasts: true,
        },
      },
    })

    const ensureSessionValidation = (shellMocks.useNotificationRuntime as any).capturedEnsure
    await ensureSessionValidation()
    expect(shellMocks.apiFetch).not.toHaveBeenCalled()

    localStorage.setItem('refresh_token', 'refresh-token')
    await expect(ensureSessionValidation()).resolves.toBeUndefined()
  })
})

import { beforeEach, describe, expect, it, vi } from 'vitest'
import { flushPromises, mount } from '@vue/test-utils'
import { createPinia, setActivePinia } from 'pinia'
import { nextTick, reactive } from 'vue'

const apiFetchMock = vi.fn()
const routeState = reactive({ name: 'home' })

function setViewport(width: number, height: number) {
  Object.defineProperty(window, 'innerWidth', { configurable: true, writable: true, value: width })
  Object.defineProperty(window, 'innerHeight', { configurable: true, writable: true, value: height })
  window.dispatchEvent(new Event('resize'))
}

vi.mock('vue-router', () => ({
  useRoute: () => routeState,
}))

vi.mock('../utils/auth', () => ({
  apiFetch: apiFetchMock,
}))

describe('BottomNav.vue', () => {
  beforeEach(() => {
    vi.resetModules()
    setActivePinia(createPinia())
    apiFetchMock.mockReset()
    localStorage.clear()
    routeState.name = 'home'
    setViewport(1024, 768)
  })

  it('adds canonical navigation hooks only for an explicitly scoped V2 shell', async () => {
    const BottomNav = (await import('./BottomNav.vue')).default
    const global = {
      stubs: {
        'router-link': {
          props: ['to'],
          template: '<a v-bind="$attrs"><slot /></a>',
        },
      },
    }

    const legacyWrapper = mount(BottomNav, { global })
    expect(legacyWrapper.find('[class*="ui-v2-bottom-nav"]').exists()).toBe(false)
    legacyWrapper.unmount()

    const v2Wrapper = mount(BottomNav, { props: { v2Scope: true }, global })
    expect(v2Wrapper.get('nav').classes()).toContain('ui-v2-bottom-nav')
    expect(v2Wrapper.get('.bottom-nav-bar').classes()).toContain('ui-v2-bottom-nav-bar')
    expect(v2Wrapper.findAll('.ui-v2-bottom-nav-item')).toHaveLength(
      v2Wrapper.findAll('.nav-item').length,
    )
    expect(v2Wrapper.findAll('.ui-v2-bottom-nav-label')).toHaveLength(
      v2Wrapper.findAll('.nav-label').length,
    )
    v2Wrapper.unmount()
  })

  it('shows the operations entry immediately from the cached role on first mount', async () => {
    localStorage.setItem('current_user_summary', JSON.stringify({
      id: 1,
      role: 'مدیر ارشد',
      account_name: 'mohsen',
    }))
    apiFetchMock.mockRejectedValue(new Error('temporary network issue'))

    const BottomNav = (await import('./BottomNav.vue')).default
    const wrapper = mount(BottomNav, {
      global: {
        stubs: {
          'router-link': {
            template: '<a><slot /></a>',
          },
        },
      },
    })

    await flushPromises()

    expect(wrapper.text()).toContain('عملیات')
    expect(wrapper.text()).not.toContain('مدیریت')
    wrapper.unmount()
  })

  it('primes the current user, toggles the FAB menu, collapses on route changes, and renders disabled plus capped unread states', async () => {
    localStorage.setItem('auth_token', 'jwt-token')
    routeState.name = 'market'
    apiFetchMock.mockResolvedValue({
      ok: true,
      json: async () => ({ id: 2, role: 'عادی', account_name: 'normal-user' }),
    })

    const currentUserModule = await import('../utils/currentUser')
    currentUserModule.clearCurrentUserSummary()

    const BottomNav = (await import('./BottomNav.vue')).default
    const wrapper = mount(BottomNav, {
      global: {
        stubs: {
          'router-link': {
            props: ['to'],
            template: '<a :href="typeof to === \'string\' ? to : to.path"><slot /></a>',
          },
        },
      },
    })

    await flushPromises()
    expect(apiFetchMock).toHaveBeenCalledWith('/api/auth/me')

    await wrapper.get('.fab-btn').trigger('click')
    expect(wrapper.find('.fab-nav').exists()).toBe(true)

    ;(wrapper.vm as any).navItems[0].disabled = true
    const storeModule = await import('../stores/notifications')
    const notificationStore = storeModule.useNotificationStore()
    notificationStore.setChatUnreadCount(120)
    await nextTick()
    await flushPromises()

    expect(wrapper.find('.fab-unread-badge').text()).toBe('9+')

    routeState.name = 'home'
    await nextTick()
    await flushPromises()

    expect(wrapper.find('.fab-nav').exists()).toBe(false)
    expect(wrapper.find('.soon-dot').exists()).toBe(true)
    expect(wrapper.find('.nav-unread-badge').text()).toBe('99+')

    wrapper.unmount()
  })

  it('hides the market entry for accountant users from the cached summary', async () => {
    localStorage.setItem('current_user_summary', JSON.stringify({
      id: 9,
      role: 'عادی',
      account_name: 'accountant9',
      is_accountant: true,
    }))
    apiFetchMock.mockRejectedValue(new Error('temporary network issue'))

    const BottomNav = (await import('./BottomNav.vue')).default
    const wrapper = mount(BottomNav, {
      global: {
        stubs: {
          'router-link': {
            template: '<a><slot /></a>',
          },
        },
      },
    })

    await flushPromises()

    expect(wrapper.text()).not.toContain('بازار')
    wrapper.unmount()
  })

  it('keeps operations and account tabs active for the new workspace route names', async () => {
    localStorage.setItem('current_user_summary', JSON.stringify({
      id: 14,
      role: 'عادی',
      account_name: 'route-user',
    }))
    apiFetchMock.mockRejectedValue(new Error('temporary network issue'))

    const BottomNav = (await import('./BottomNav.vue')).default
    const wrapper = mount(BottomNav, {
      global: {
        stubs: {
          'router-link': {
            props: ['to'],
            template: '<a class="nav-link-stub"><slot /></a>',
          },
        },
      },
    })

    routeState.name = 'operations-customers-detail'
    await nextTick()
    expect(wrapper.findAll('.nav-item.active').some((item) => item.text().includes('عملیات'))).toBe(true)

    routeState.name = 'admin-system'
    await nextTick()
    expect(wrapper.findAll('.nav-item.active').some((item) => item.text().includes('عملیات'))).toBe(true)

    routeState.name = 'account-storage'
    await nextTick()
    expect(wrapper.findAll('.nav-item.active').some((item) => item.text().includes('حساب'))).toBe(true)

    wrapper.unmount()
  })

  it('shows a red closed marker on the market navigation item when the market is closed', async () => {
    localStorage.setItem('auth_token', 'jwt-token')
    apiFetchMock.mockImplementation(async (path: string) => {
      if (path === '/api/trading-settings/market-state') {
        return {
          ok: true,
          json: async () => ({
            is_open: false,
            active_web_notice_visible: true,
            offers_since_last_open: 0,
            last_transition_at: '2026-06-12T10:00:00Z',
            next_transition_at: '2026-06-13T06:00:00Z',
          }),
        }
      }
      if (path === '/api/auth/me') {
        return {
          ok: true,
          json: async () => ({ id: 3, role: 'عادی', account_name: 'market-user' }),
        }
      }
      return { ok: true, json: async () => null }
    })

    const currentUserModule = await import('../utils/currentUser')
    currentUserModule.clearCurrentUserSummary()

    const BottomNav = (await import('./BottomNav.vue')).default
    const wrapper = mount(BottomNav, {
      global: {
        stubs: {
          'router-link': {
            props: ['to'],
            template: '<a v-bind="$attrs" :href="typeof to === \'string\' ? to : to.path"><slot /></a>',
          },
        },
      },
    })

    await flushPromises()
    await nextTick()

    const marketItem = wrapper.get('.nav-item.market-closed')
    expect(marketItem.text()).toContain('بازار')
    expect(marketItem.get('.market-closed-text').text()).toBe('بسته')

    wrapper.unmount()
  })

  it('restores the persisted FAB position for messenger and ignores malformed stored coordinates', async () => {
    routeState.name = 'messenger'
    localStorage.setItem('fab_position', JSON.stringify({ x: 88, y: 144 }))

    const BottomNav = (await import('./BottomNav.vue')).default
    const wrapper = mount(BottomNav, {
      global: {
        stubs: {
          'router-link': {
            template: '<a><slot /></a>',
          },
        },
      },
    })

    await flushPromises()

    const fabContainer = wrapper.get('.fab-container')
    expect(fabContainer.attributes('style')).toContain('left: 88px;')
    expect(fabContainer.attributes('style')).toContain('top: 144px;')
    expect(fabContainer.attributes('style')).toContain('bottom: auto;')
    expect(fabContainer.attributes('style')).toContain('right: auto;')

    wrapper.unmount()

    localStorage.setItem('fab_position', '{bad json')
    const malformedWrapper = mount(BottomNav, {
      global: {
        stubs: {
          'router-link': {
            template: '<a><slot /></a>',
          },
        },
      },
    })

    await flushPromises()

    expect(malformedWrapper.get('.fab-container').attributes('style') || '').not.toContain('left:')
    malformedWrapper.unmount()
  })

  it('ignores non-numeric saved FAB coordinates and supports touch dragging with changedTouches fallback', async () => {
    vi.useFakeTimers()
    routeState.name = 'market'
    localStorage.setItem('fab_position', JSON.stringify({ x: '88', y: 144 }))

    const BottomNav = (await import('./BottomNav.vue')).default
    const wrapper = mount(BottomNav, {
      attachTo: document.body,
      global: {
        stubs: {
          'router-link': {
            template: '<a><slot /></a>',
          },
        },
      },
    })

    await flushPromises()
    expect(wrapper.get('.fab-container').attributes('style') || '').not.toContain('left:')

    await wrapper.get('.fab-btn').trigger('touchstart', {
      touches: [{ clientX: 10, clientY: 10 }],
    })

    const touchMove = new Event('touchmove', { bubbles: true, cancelable: true })
    Object.defineProperty(touchMove, 'touches', { value: [] })
    Object.defineProperty(touchMove, 'changedTouches', { value: [{ clientX: 170, clientY: 210 }] })
    document.dispatchEvent(touchMove)
    await nextTick()

    const touchEnd = new Event('touchend', { bubbles: true })
    Object.defineProperty(touchEnd, 'changedTouches', { value: [{ clientX: 170, clientY: 210 }] })
    document.dispatchEvent(touchEnd)
    await nextTick()

    const storedPosition = JSON.parse(localStorage.getItem('fab_position') || '{}')
    expect(storedPosition).toMatchObject({ x: 160, y: 200 })

    await vi.advanceTimersByTimeAsync(60)
    await wrapper.get('.fab-btn').trigger('click')
    expect(wrapper.find('.fab-nav').exists()).toBe(true)

    wrapper.unmount()
    vi.useRealTimers()
  })

  it('renders disabled entries inside the expanded FAB menu when a nav item is flagged disabled', async () => {
    routeState.name = 'market'

    const BottomNav = (await import('./BottomNav.vue')).default
    const wrapper = mount(BottomNav, {
      global: {
        stubs: {
          'router-link': {
            template: '<a><slot /></a>',
          },
        },
      },
    })

    await flushPromises()

    ;(wrapper.vm as any).navItems[0].disabled = true
    await nextTick()

    await wrapper.get('.fab-btn').trigger('click')
    await nextTick()

    const disabledFabItem = wrapper.find('.fab-item.disabled')
    expect(disabledFabItem.exists()).toBe(true)
    expect(disabledFabItem.text()).toContain('خانه')

    wrapper.unmount()
  })

  it('positions the expanded FAB menu toward visible viewport space near screen edges', async () => {
    routeState.name = 'market'
    setViewport(390, 720)
    localStorage.setItem('fab_position', JSON.stringify({ x: 346, y: 8 }))

    const BottomNav = (await import('./BottomNav.vue')).default
    const wrapper = mount(BottomNav, {
      attachTo: document.body,
      global: {
        stubs: {
          'router-link': {
            props: ['to'],
            template: '<a :href="typeof to === \'string\' ? to : to.path"><slot /></a>',
          },
        },
      },
    })

    await flushPromises()
    await wrapper.get('.fab-btn').trigger('click')
    await nextTick()

    const topRightMenu = wrapper.get('.fab-nav')
    expect(topRightMenu.classes()).toEqual(expect.arrayContaining(['fab-nav--down', 'fab-nav--left']))
    expect(topRightMenu.attributes('style')).toContain('top: 56px;')
    expect(topRightMenu.attributes('style')).toContain('bottom: auto;')
    expect(topRightMenu.attributes('style')).toContain('right: 0')
    expect(topRightMenu.attributes('style')).toContain('left: auto;')

    wrapper.unmount()

    localStorage.setItem('fab_position', JSON.stringify({ x: 346, y: 676 }))
    const bottomRightWrapper = mount(BottomNav, {
      attachTo: document.body,
      global: {
        stubs: {
          'router-link': {
            props: ['to'],
            template: '<a :href="typeof to === \'string\' ? to : to.path"><slot /></a>',
          },
        },
      },
    })

    await flushPromises()
    await bottomRightWrapper.get('.fab-btn').trigger('click')
    await nextTick()

    const bottomRightMenu = bottomRightWrapper.get('.fab-nav')
    expect(bottomRightMenu.classes()).toEqual(expect.arrayContaining(['fab-nav--up', 'fab-nav--left']))
    expect(bottomRightMenu.attributes('style')).toContain('bottom: 56px;')
    expect(bottomRightMenu.attributes('style')).toContain('top: auto;')
    expect(bottomRightMenu.attributes('style')).toContain('right: 0')
    expect(bottomRightMenu.attributes('style')).toContain('left: auto;')

    bottomRightWrapper.unmount()
  })

  it('drags the FAB with mouse events, persists the bounded position, and ignores toggle clicks while dragging', async () => {
    vi.useFakeTimers()
    routeState.name = 'market'

    const BottomNav = (await import('./BottomNav.vue')).default
    const wrapper = mount(BottomNav, {
      attachTo: document.body,
      global: {
        stubs: {
          'router-link': {
            props: ['to'],
            template: '<a :href="typeof to === \'string\' ? to : to.path"><slot /></a>',
          },
        },
      },
    })

    await flushPromises()

    const fabButton = wrapper.get('.fab-btn')
    await fabButton.trigger('mousedown', { clientX: 10, clientY: 10 })
    document.dispatchEvent(new MouseEvent('mousemove', { clientX: 4000, clientY: 4000, bubbles: true, cancelable: true }))
    await nextTick()

    expect(wrapper.find('.fab-nav').exists()).toBe(false)

    document.dispatchEvent(new MouseEvent('mouseup', { bubbles: true }))
    await nextTick()

    const storedPosition = JSON.parse(localStorage.getItem('fab_position') || '{}')
    expect(storedPosition.x).toBe(window.innerWidth - 44)
    expect(storedPosition.y).toBe(window.innerHeight - 44 - 112)
    expect(wrapper.get('.fab-container').attributes('style')).toContain(`left: ${window.innerWidth - 44}px;`)
    expect(wrapper.get('.fab-container').attributes('style')).toContain(`top: ${window.innerHeight - 44 - 112}px;`)
    expect(wrapper.get('.fab-container').classes()).toContain('fab-container--market')
    expect(fabButton.attributes('type')).toBe('button')
    expect(fabButton.attributes('aria-label')).toBe('باز کردن ناوبری')
    expect(fabButton.attributes('aria-expanded')).toBe('false')

    await vi.advanceTimersByTimeAsync(60)
    await fabButton.trigger('click')
    expect(wrapper.find('.fab-nav').exists()).toBe(true)
    expect(fabButton.attributes('aria-label')).toBe('بستن ناوبری')
    expect(fabButton.attributes('aria-expanded')).toBe('true')

    wrapper.unmount()
    vi.useRealTimers()
  })
})

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { flushPromises, mount } from '@vue/test-utils'

const apiFetchMock = vi.fn()

vi.mock('../utils/auth', () => ({
  apiFetch: apiFetchMock,
}))

function makeResponse(payload: unknown, ok = true) {
  return {
    ok,
    json: async () => payload,
  }
}

function boundedRequestOptions(options: Record<string, unknown> = {}) {
  return expect.objectContaining({
    ...options,
    retryNetwork: false,
    signal: expect.any(AbortSignal),
    trackConnectionState: false,
  })
}

function makeRelation(overrides: Record<string, unknown> = {}) {
  return {
    id: 1,
    owner_user_id: 7,
    accountant_user_id: null,
    accountant_account_name: null,
    global_account_name: 'acc1',
    relation_display_name: 'حسابدار اول',
    duty_description: 'پیگیری',
    mobile_number: '09120000000',
    status: 'pending',
    web_short_link: 'https://app.example/i/ACCT0001',
    expires_at: '2026-01-03T10:00:00',
    activated_at: null,
    deleted_at: null,
    created_at: '2026-01-01T10:00:00',
    ...overrides,
  }
}

async function mountModal(props: Record<string, unknown> = {}) {
  const OwnerAccountantManagerModal = (await import('./OwnerAccountantManagerModal.vue')).default
  const wrapper = mount(OwnerAccountantManagerModal, {
    props,
    global: {
      stubs: {
        teleport: true,
      },
    },
  })
  await flushPromises()
  return wrapper
}

async function openCreatePanel(wrapper: any) {
  await wrapper.findAll('.accountant-main-menu-header')[0].trigger('click')
  await flushPromises()
}

async function openRelationsPanel(wrapper: any) {
  await wrapper.findAll('.accountant-main-menu-header')[1].trigger('click')
  await flushPromises()
}

async function openFirstAccountantDetail(wrapper: any) {
  await wrapper.get('.accountant-settings-btn').trigger('click')
  await flushPromises()
}

async function openDetailSection(wrapper: any, index: number) {
  await wrapper.findAll('.detail-accordion > .accountant-accordion-header')[index].trigger('click')
  await flushPromises()
}

